#!/usr/bin/env python3
"""Fig. 1: collage that reads "CVPR" (top row) and "20 | KalSea | 27" (bottom row), all generated by FLUX.1-dev at
1024x1024 with our cache (delta 0.2). Writes ../fig_collage.jpg, ../fig_collage_caption.tex (Fig. 1 caption),
../../tables/supp_collage.tex (prompts and seeds, supplement) and data/collage.json (prompts, seeds, NFE; no paths).

    python make_collage.py

Layout: top row 4 square tiles of side T; bottom row a square tile, the billboard cropped to 2:1 (width 2T + G, the
centre band of the 1024x1024 image) and a square tile, so both rows have width 4T + 3G. Tiles are downscaled with
Lanczos; nothing else is edited.
"""
import glob
import json
import os

from PIL import Image

import data_sources as DS

HERE = os.path.dirname(os.path.abspath(__file__))
T, G = 512, 10                       # tile side and gutter (pixels)


def candidates():
    rows = {}
    for f in glob.glob(os.path.join(DS.COLLAGE_RAW, "stats_shard*.jsonl")):
        for line in open(f):
            r = json.loads(line)
            rows[r["idx"]] = r
    return rows


def main():
    rows = candidates()
    assert len(rows) == 28, len(rows)
    img = {}
    for key, idx in DS.COLLAGE_PICK.items():
        r = rows[idx]
        im = Image.open(os.path.join(DS.COLLAGE_RAW, os.path.basename(r["file"]))).convert("RGB")
        assert im.size == (1024, 1024), im.size
        img[key] = im
    W, H = 4 * T + 3 * G, 2 * T + G
    canvas = Image.new("RGB", (W, H), "white")
    for k, key in enumerate(("C", "V", "P", "R")):
        canvas.paste(img[key].resize((T, T), Image.LANCZOS), (k * (T + G), 0))
    bw = 2 * T + G
    band = img["KalSea"].crop((0, 256, 1024, 768)).resize((bw, T), Image.LANCZOS)   # centre 2:1 band
    canvas.paste(img["20"].resize((T, T), Image.LANCZOS), (0, T + G))
    canvas.paste(band, (T + G, T + G))
    canvas.paste(img["27"].resize((T, T), Image.LANCZOS), (T + G + bw + G, T + G))
    canvas.save(os.path.join(HERE, "..", "fig_collage.jpg"), quality=92, subsampling=0)
    meta = {"model": "FLUX.1-dev", "resolution": "1024x1024", "steps": 50, "delta": rows[DS.COLLAGE_PICK["C"]]["delta"],
            "tiles": {key: {"prompt": rows[i]["prompt"], "seed": rows[i]["seed"], "nfe": rows[i]["nfe"],
                            "method": rows[i]["method"]} for key, i in DS.COLLAGE_PICK.items()},
            "nfe_all_candidates": sorted({r["nfe"] for r in rows.values()})}
    json.dump(meta, open(os.path.join(HERE, "data", "collage.json"), "w"), indent=1)
    nfe = sorted({v["nfe"] for v in meta["tiles"].values()})
    assert len(nfe) == 1, nfe
    n = nfe[0]
    cap = ("% Auto-generated by figures/src/make_collage.py (data/collage.json).\n"
           "\\caption{\\textbf{Generated by our cache.} Each tile is a \\flux image ($1024{\\times}1024$, 50 steps) generated"
           f" with \\ours at $\\delta={meta['delta']}$, i.e.\\ {n} of 50 transformer evaluations ({50 / n:.2f}$\\times$ fewer);"
           " the tiles are only downscaled, and the billboard is the central 2:1 band of its image. Prompts and seeds:"
           " supplement.}\n\\label{fig:collage}\n")
    open(os.path.join(HERE, "..", "fig_collage_caption.tex"), "w").write(cap)
    esc = lambda t: t.replace("\\", "\\textbackslash{}").replace("&", "\\&").replace("%", "\\%").replace("_", "\\_")
    lines = ["% Auto-generated by figures/src/make_collage.py (data/collage.json) -- edit the generator, not this file.",
             "\\begin{table*}[t]", "  \\centering",
             "  \\caption{\\textbf{Prompts of the main paper's \\maincref{fig:collage}} (\\flux, $1024{\\times}1024$, 50 steps,"
             f" guidance 3.5, \\ours at $\\delta={meta['delta']}$, {n} of 50 transformer evaluations per image). Four seeds were"
             " generated per prompt and one was picked by eye for legible lettering.}",
             "  \\label{tab:collage-prompts}", "  \\footnotesize", "  \\begin{tabular}{@{}llp{0.78\\textwidth}@{}}",
             "    \\toprule", "    Tile & Seed & Prompt \\\\", "    \\midrule"]
    for key, v in meta["tiles"].items():
        lines.append(f"    {key} & {v['seed']} & {esc(v['prompt'])} \\\\")
    lines += ["    \\bottomrule", "  \\end{tabular}", "\\end{table*}", ""]
    open(os.path.join(HERE, "..", "..", "tables", "supp_collage.tex"), "w").write("\n".join(lines))
    print("collage", W, "x", H, "| NFE of the tiles:", {k: v["nfe"] for k, v in meta["tiles"].items()},
          "| method:", meta["tiles"]["C"]["method"])


if __name__ == "__main__":
    main()
